WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY age DESC NULLS FIRST, id ASC) AS latest_rank FROM customers) x WHERE latest_rank = 1) SELECT city, country, SUM(age) FILTER (WHERE city = 'Tokyo') AS tokyo_total_age, SORT_ARRAY(COLLECT_SET(city)) AS city_list, SUM(credit_limit) AS total_credit_limit, CORR(age, credit_limit) AS corr_age_credit_limit, COUNT(CASE WHEN segment = 'SMB' THEN 1 END) AS smb_count, SIZE(COLLECT_SET(segment)) AS num_segments FROM latest GROUP BY city, country HAVING SIZE(COLLECT_SET(segment)) >= 1 ORDER BY num_segments DESC
